parameters.jsCode:
// Parse incoming payload from Slack Block Kit button click
let payload = $input.first().json;

if (payload.body && typeof payload.body.payload === 'string') {
  payload = JSON.parse(payload.body.payload);
} else if (typeof payload.payload === 'string') {
  payload = JSON.parse(payload.payload);
}

const user = payload.user || {};
const userId = user.id || '';
const userName = user.name || user.username || 'Student';
const channelId = (payload.channel && payload.channel.id) ? payload.channel.id : 'C0C0U2PJ43A';
const responseUrl = payload.response_url || '';

const now = new Date();
const day = String(now.getDate()).padStart(2, '0');
const month = String(now.getMonth() + 1).padStart(2, '0');
const year = now.getFullYear();
const todayDateStr = `${day}-${month}-${year}`;

return [{
  json: {
    userId,
    userName,
    channelId,
    responseUrl,
    todayDateStr,
    timestamp: now.toISOString()
  }
}];

